"""Add license/provenance to exported GLB metadata; no geometry or motion changes."""
import struct,json
from pathlib import Path
for file,source,license,status in [('video-prototype.glb','FitnessScape, Squat - exercise demonstration video, via Wikimedia Commons; modified by local pose estimation and retargeting','Motion derivative CC BY 3.0 https://creativecommons.org/licenses/by/3.0/ ; Rocketbox model MIT Copyright Microsoft 2020','REJECTED_FOR_RUNTIME'),('mocap-prototype.glb','CMU Graphics Lab mocap.cs.cmu.edu, NSF EIA-0196217, 22_14; BVH conversion Bruce Hahne; excerpt and retargeting','CMU: may copy/modify/redistribute; commercial products allowed, no resale of data alone even converted. Rocketbox model MIT Copyright Microsoft 2020','HOLD')]:
 p=Path('docs/coach/phase5')/file;b=p.read_bytes();n=struct.unpack_from('<I',b,12)[0];doc=json.loads(b[20:20+n]);doc['asset']['extras']={'source':source,'license':license,'status':status,'professionalReview':False,'runtimeEnabled':False,'notice':'Read docs/coach/phase5/ATTRIBUTION.md. No endorsement; research only.'};js=json.dumps(doc,separators=(',',':')).encode();js+=b' '*((-len(js))%4);tail=b[20+n:];p.write_bytes(struct.pack('<III',0x46546c67,2,20+len(js)+len(tail))+struct.pack('<II',len(js),0x4e4f534a)+js+tail)
